package com.bank.stream;

import java.math.BigDecimal;

// A transaction with the wall-clock time it arrived at the engine.
class Txn {
    private final String txnId;
    private final String accountId;
    private final BigDecimal amount;
    private final long arrivalMillis;

    Txn(String txnId, String accountId, BigDecimal amount, long arrivalMillis) {
        this.txnId = txnId;
        this.accountId = accountId;
        this.amount = amount;
        this.arrivalMillis = arrivalMillis;
    }

    String getTxnId() { return txnId; }
    String getAccountId() { return accountId; }
    BigDecimal getAmount() { return amount; }
    long getArrivalMillis() { return arrivalMillis; }
}
