package com.bank.stream;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Flink-style true streaming: each event processed the instant it arrives.
class ContinuousProcessor {
    private static final Logger log = Logger.getLogger(ContinuousProcessor.class.getName());
    private final BigDecimal fraudThreshold = new BigDecimal("500000");

    // Returns the processing latency (ms) for this single event.
    long process(Txn t, long nowMillis) {
        long latency = nowMillis - t.getArrivalMillis(); // ~0, no batch wait
        if (t.getAmount().compareTo(fraudThreshold) > 0) {
            log.warning(() -> "FRAUD ALERT " + t.getTxnId() + " amount=" + t.getAmount()
                    + " latency=" + latency + "ms");
        } else {
            log.info(() -> "processed " + t.getTxnId() + " latency=" + latency + "ms");
        }
        return latency;
    }
}
