package com.bank.stream;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Spark-style micro-batch: events buffer until the batch interval elapses,
// then the whole batch is processed together.
class MicroBatchProcessor {
    private static final Logger log = Logger.getLogger(MicroBatchProcessor.class.getName());
    private final long batchIntervalMs;
    private final List<Txn> buffer = new ArrayList<>();
    private long lastTriggerMillis = 0;

    MicroBatchProcessor(long batchIntervalMs) { this.batchIntervalMs = batchIntervalMs; }

    void add(Txn t) { buffer.add(t); }

    // Called by the engine clock; fires only when the interval elapses.
    // Returns the list of per-event latencies for the fired batch (empty if not fired).
    List<Long> maybeTrigger(long nowMillis) {
        List<Long> latencies = new ArrayList<>();
        if (nowMillis - lastTriggerMillis >= batchIntervalMs && !buffer.isEmpty()) {
            for (Txn t : buffer) {
                long latency = nowMillis - t.getArrivalMillis(); // includes batch wait
                latencies.add(latency);
                log.info(() -> "batch-processed " + t.getTxnId() + " latency=" + latency + "ms");
            }
            log.info("micro-batch of " + buffer.size() + " txns fired at " + nowMillis);
            buffer.clear();
            lastTriggerMillis = nowMillis;
        }
        return latencies;
    }
}
