package com.bank.stream;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class EngineComparisonDemo {
    private static final Logger log = Logger.getLogger(EngineComparisonDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // Transactions arriving at 0,200,400,600,800 ms.
        List<Txn> txns = new ArrayList<>();
        txns.add(new Txn("T1", "SAV2001", new BigDecimal("600000"), 0));     // fraud
        txns.add(new Txn("T2", "CUR3001", new BigDecimal("12000"), 200));
        txns.add(new Txn("T3", "SAV2001", new BigDecimal("50000"), 400));
        txns.add(new Txn("T4", "CUR3001", new BigDecimal("700000"), 600));   // fraud
        txns.add(new Txn("T5", "SAV2002", new BigDecimal("3000"), 800));

        // Flink-style: processed at arrival time (latency ~0).
        ContinuousProcessor flink = new ContinuousProcessor();
        long flinkSum = 0;
        for (Txn t : txns) flinkSum += flink.process(t, t.getArrivalMillis());
        log.info("Flink avg latency = " + (flinkSum / txns.size()) + "ms");

        // Spark-style: 1-second batch; all 5 processed at the 1000ms trigger.
        MicroBatchProcessor spark = new MicroBatchProcessor(1000);
        for (Txn t : txns) spark.add(t);
        List<Long> sparkLat = spark.maybeTrigger(1000);
        long sparkSum = sparkLat.stream().mapToLong(Long::longValue).sum();
        log.info("Spark avg latency = " + (sparkSum / sparkLat.size()) + "ms");
    }
}

